namespace TreeSpitter;

/// <summary>
/// Generates a precompiled parser in a partial class, with the TreeSpitter source generator: the grammar is compiled
/// at build time, its tables are embedded and its keywords are matched by code. The grammar is a <c>grammar.json</c> file
/// (as generated by <c>tree-sitter generate</c> or <c>treespitter grammar</c>) added to the project as an
/// <c>AdditionalFiles</c> item. The class gets a static <c>Language</c> property and a <c>CreateParser()</c> method.
/// </summary>
[AttributeUsage(AttributeTargets.Class, AllowMultiple = false, Inherited = false)]
public sealed class GeneratedLanguageAttribute : Attribute
{
    /// <summary>Creates the attribute.</summary>
    /// <param name="grammarPath">The path of the <c>grammar.json</c> file, matched against the end of the paths of the additional files.</param>
    public GeneratedLanguageAttribute(string grammarPath)
    {
        GrammarPath = grammarPath;
    }

    /// <summary>Gets the path of the <c>grammar.json</c> file.</summary>
    public string GrammarPath { get; }

    /// <summary>
    /// Gets or sets the external scanner of the grammar's <c>externals</c>: a class implementing
    /// <see cref="IExternalScanner"/> with a parameterless constructor.
    /// </summary>
    public Type? ExternalScanner { get; set; }
}
